function Badge({ x }: { x: number }) {
  return (
    <g transform={`translate(${x} 0)`}>
      <path className="logo__badge" d={BADGE} />
      <path className="logo__badge-text" d={BADGE_TEXT} />
    </g>
  );
}

/**
 * aunoo wordmark with the BETA pill, for dark chrome. With `collapsible`, the short "au" version
 * replaces it when the sidebar is a rail. Brand artwork colours come from the --logo-* tokens.
 */
export function Logo({ label = 'aunoo Beta', collapsible = false, className }: LogoProps) {
  return (
    <span className={['logo', collapsible && 'logo--collapsible', className].filter(Boolean).join(' ')} role="img" aria-label={label}>
      <svg className="logo__full" viewBox="0 0 176 24" aria-hidden="true" focusable="false">
        <path className="logo__word" d={WORD_A} />
        <path className="logo__word" d={WORD_U} />
        {WORD_NOO.map((d) => <path key={d.slice(0, 12)} className="logo__word" d={d} />)}
        <path className="logo__dot" d={DOT} />
        <Badge x={135} />
      </svg>
      {collapsible && (
        <svg className="logo__mark" viewBox="0 0 96 24" aria-hidden="true" focusable="false">
          <path className="logo__word" d={WORD_A} />
          <path className="logo__word" d={WORD_U} />
          <path className="logo__dot" d={DOT} />
          <Badge x={54.8783} />
        </svg>
      )}
    </span>
  );
}
